        protocol = q.get("protocol", "1")
        receipts = q.get("receipts", [])
        accepted_count, duplicate_count = summarize_receipts(receipts)
        return {
            "protocol": protocol,
            "accepted_count": accepted_count,
            "duplicate_count": duplicate_count
        }

